import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · Lesson 42 Modern cavemen","description":"学习 独立主格的独立主语，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 42 Modern cavemen","description":"学习 独立主格的独立主语，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 独立主格的独立主语，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 41 Illusions of pastoral peace","link":"/life/english/new-concept/book-3/unit-03/lesson-041"},"next":{"text":"第三册：培养技能 · Lesson 43 Fully insured","link":"/life/english/new-concept/book-3/unit-03/lesson-043"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 41 Illusions of pastoral peace","link":"/life/english/new-concept/book-3/unit-03/lesson-041"},"next":{"text":"第三册：培养技能 · Lesson 43 Fully insured","link":"/life/english/new-concept/book-3/unit-03/lesson-043"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-03/lesson-042.md","filePath":"life/english/new-concept/book-3/unit-03/lesson-042.md"}'),r={name:"life/english/new-concept/book-3/unit-03/lesson-042.md"};function l(s,e,i,d,h,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第三册-培养技能-·-lesson-42-modern-cavemen" tabindex="-1">第三册：培养技能 · Lesson 42 Modern cavemen <a class="header-anchor" href="#第三册-培养技能-·-lesson-42-modern-cavemen" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 42 Modern cavemen&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>以洞穴探索与团队准备讨论复杂路线说明。探险叙述应交代照明、通道和人员位置，不能只渲染神秘感。学习独立主格结构如何补充环境条件，同时明确它的书面语性质，在容易产生歧义时优先选择完整从句，让不同主语的动作关系清楚。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>chamber</td><td>/ˈtʃeɪmbə/</td><td>n.</td><td>洞室</td><td>an underground chamber</td></tr><tr><td>passage</td><td>/ˈpæsɪdʒ/</td><td>n.</td><td>通道</td><td>a narrow passage</td></tr><tr><td>torch</td><td>/tɔːtʃ/</td><td>n.</td><td>手电筒</td><td>a spare torch</td></tr><tr><td>exploration</td><td>/ˌekspləˈreɪʃən/</td><td>n.</td><td>探索</td><td>careful exploration</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>make one&#39;s way — 设法前进</li><li>in single file — 排成单列</li></ul><h2 id="语法讲解-独立主格的独立主语" tabindex="-1">语法讲解：独立主格的独立主语 <a class="header-anchor" href="#语法讲解-独立主格的独立主语" aria-label="Permalink to &quot;语法讲解：独立主格的独立主语&quot;">​</a></h2><p>名词或代词加分词等成分可构成独立主格，为主句补充时间、原因或伴随情况，其逻辑主语不同于主句主语。The entrance blocked, we chose another route 中 blocked 与 entrance 构成被动关系。主动进行可用 ing，完成或被动可用过去分词，某些结构也可用形容词或介词短语。它不是完整的限定分句，不能仅用逗号连接两个都有完整谓语的独立句。该形式较书面；信息复杂时改为 because 或 when 从句通常更易理解。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The main passage blocked, the team returned to the entrance.</p></blockquote><p>主通道被堵住了，团队便返回入口。</p><p>the main passage 为独立结构主语，blocked 表被动状态；主句主语为 the team。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>The passage was blocked, the team returned 属于逗号拼接两个完整句，需加 so、用分号或改为从句。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>先读 Our spare lights ready 后短停，再接主句；尝试改读 With our spare lights ready，比较信息边界是否更清楚。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Our spare lights ready, we entered the first chamber. Water soon covered the lower steps. We returned before the rising level blocked the exit.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句写虚构地下通道检查，包含环境变化和团队决定。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>独立结构说明准备状态，后两句给出观察和及时调整。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>把例句改为 because 从句。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Because the main passage was blocked, the team returned to the entrance.</p><p><strong>解析：</strong> 恢复明确主语和限定谓语。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>blocked 描述谁的状态？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> the main passage</p><p><strong>解析：</strong> 不是 the team。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>修正标点：It was dark, we stopped.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> It was dark, so we stopped.</p><p><strong>解析：</strong> 使用连词连接完整分句。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：独立主格的独立主语。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-041">上一课</a> · <a href="/life/english/new-concept/book-3/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-03/lesson-043">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(r,[["render",l]]);export{u as __pageData,b as default};
